using System.Diagnostics;
using System.Drawing;
using System.Text.RegularExpressions;
namespace RF4FriendLauncher;
public sealed class MainForm:Form
{
 readonly LauncherConfig cfg;readonly AccountService account=new();readonly HostsService hosts=new();
 readonly TextBox ip=new(),user=new(),pass=new(),game=new();readonly ComboBox region=new();readonly CheckBox auto=new();readonly Label uid=new(),status=new();
 public MainForm(){cfg=ConfigService.Load();Text="RF4 Friend Launcher";StartPosition=FormStartPosition.CenterScreen;MinimumSize=new Size(720,650);Size=new Size(760,690);Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(245,247,250);Build();LoadCfg();Shown+=async(_,_)=>{if(auto.Checked&&!string.IsNullOrWhiteSpace(user.Text)&&pass.Text!="")await Auth(false,false);};}
 void Build(){var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(22),ColumnCount=1,RowCount=5};root.RowStyles.Add(new RowStyle(SizeType.Absolute,52));root.RowStyles.Add(new RowStyle(SizeType.Absolute,205));root.RowStyles.Add(new RowStyle(SizeType.Absolute,155));root.RowStyles.Add(new RowStyle(SizeType.Absolute,70));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));Controls.Add(root);root.Controls.Add(new Label{Text="RF4 Friend Launcher",Font=new Font("Segoe UI Semibold",19),Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft},0,0);root.Controls.Add(AccountPanel(),0,1);root.Controls.Add(GamePanel(),0,2);root.Controls.Add(ActionPanel(),0,3);var f=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2};f.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,130));f.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));f.RowStyles.Add(new RowStyle(SizeType.Absolute,30));f.RowStyles.Add(new RowStyle(SizeType.Percent,100));uid.Text=cfg.AccountUid>0?"UID: "+cfg.AccountUid:"UID: —";uid.Dock=DockStyle.Fill;status.Text="Режим: не выбран";status.Dock=DockStyle.Fill;status.ForeColor=Color.FromArgb(70,80,95);f.Controls.Add(uid,0,0);f.Controls.Add(status,1,0);var hint=new Label{Text="Логин и пароль сохраняются локально; UID назначает только сервер.",Dock=DockStyle.Fill,ForeColor=Color.FromArgb(95,105,120),Font=new Font("Segoe UI",8.5f)};f.Controls.Add(hint,0,1);f.SetColumnSpan(hint,2);root.Controls.Add(f,0,4);}
 Control AccountPanel(){var g=new GroupBox{Text="Аккаунт",Dock=DockStyle.Fill,Padding=new Padding(12)};var t=T(4,4);t.ColumnStyles[0]=new ColumnStyle(SizeType.Absolute,75);t.ColumnStyles[2]=new ColumnStyle(SizeType.Absolute,75);t.Controls.Add(L("Логин"),0,0);t.Controls.Add(user,1,0);t.Controls.Add(L("Пароль"),2,0);t.Controls.Add(pass,3,0);user.Dock=pass.Dock=DockStyle.Fill;pass.UseSystemPasswordChar=true;var b1=B("Регистрация");var b2=B("Войти в аккаунт");b1.Click+=async(_,_)=>await Auth(true,true);b2.Click+=async(_,_)=>await Auth(false,true);t.Controls.Add(b1,1,1);t.Controls.Add(b2,3,1);auto.Text="Автоматически входить при запуске";auto.Dock=DockStyle.Fill;t.Controls.Add(auto,1,2);t.SetColumnSpan(auto,3);var n=L("Сессия");n.Text="Пароль хранится зашифрованным для этого пользователя Windows.";n.Font=new Font("Segoe UI",8.5f);n.ForeColor=Color.Gray;t.Controls.Add(n,1,3);t.SetColumnSpan(n,3);g.Controls.Add(t);return g;}
 Control GamePanel(){var g=new GroupBox{Text="Игра и сервер",Dock=DockStyle.Fill,Padding=new Padding(12)};var t=T(4,3);t.ColumnStyles[0]=new ColumnStyle(SizeType.Absolute,105);t.ColumnStyles[2]=new ColumnStyle(SizeType.Absolute,90);t.ColumnStyles[3]=new ColumnStyle(SizeType.Absolute,90);t.Controls.Add(L("IP сервера"),0,0);ip.Dock=DockStyle.Fill;t.Controls.Add(ip,1,0);var my=B("Мой сервер");my.Click+=(_,_)=>SetServer();var off=B("Официальная");off.Click+=(_,_)=>SetOfficial();t.Controls.Add(my,2,0);t.Controls.Add(off,3,0);t.Controls.Add(L("rf4_x64.exe"),0,1);game.Dock=DockStyle.Fill;t.Controls.Add(game,1,1);t.SetColumnSpan(game,2);var br=B("Обзор…");br.Click+=(_,_)=>Browse();t.Controls.Add(br,3,1);t.Controls.Add(L("Регион"),0,2);region.Items.AddRange(new object[]{"CN","RU","EU","US"});region.DropDownStyle=ComboBoxStyle.DropDownList;t.Controls.Add(region,1,2);t.SetColumnSpan(region,2);g.Controls.Add(t);return g;}
 Control ActionPanel(){var t=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2};t.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,65));t.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,35));var b=B("ЗАПУСТИТЬ ИГРУ");b.Font=new Font("Segoe UI Semibold",12);b.BackColor=Color.FromArgb(35,145,90);b.ForeColor=Color.White;b.Click+=(_,_)=>Launch();t.Controls.Add(b,0,0);t.Controls.Add(new Label{Text="UID назначается сервером",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.Gray},1,0);return t;}
 static TableLayoutPanel T(int c,int r){var t=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=c,RowCount=r};for(int i=0;i<r;i++)t.RowStyles.Add(new RowStyle(SizeType.Percent,100f/r));for(int i=0;i<c;i++)t.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100f/c));return t;}static Label L(string s)=>new(){Text=s,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft};static Button B(string s)=>new(){Text=s,Dock=DockStyle.Fill,Margin=new Padding(4)};
 void LoadCfg(){ip.Text=cfg.ServerIp;game.Text=cfg.GamePath;region.Text=string.IsNullOrWhiteSpace(cfg.GameRegion)?"CN":cfg.GameRegion;user.Text=cfg.AccountUsername;pass.Text=PasswordProtection.Unprotect(cfg.AccountPasswordProtected);auto.Checked=cfg.AutoLogin;try{if(hosts.Active())status.Text="Режим: мой сервер (записи лаунчера активны)";}catch{}}
 void Save(){cfg.ServerIp=ip.Text.Trim();cfg.GamePath=game.Text.Trim();cfg.GameRegion=region.Text.Trim();cfg.AccountUsername=user.Text.Trim();cfg.AccountPasswordProtected=PasswordProtection.Protect(pass.Text);cfg.AutoLogin=auto.Checked;ConfigService.Save(cfg);}
 async Task Auth(bool register,bool show){try{if(string.IsNullOrWhiteSpace(user.Text)||string.IsNullOrEmpty(pass.Text))throw new InvalidOperationException("Введи имя аккаунта и пароль.");SetServer();var old=cfg.AccountUid;var r=register?await account.RegisterAsync(user.Text.Trim(),pass.Text):await account.LoginAsync(user.Text.Trim(),pass.Text);SessionService.Save(user.Text.Trim(),r.LoginToken,r.TokenTimestamp);cfg.AccountUid=r.Uid;Save();uid.Text="UID: "+r.Uid;status.Text=$"Аккаунт «{user.Text.Trim()}» авторизован · UID {r.Uid} · данные сохранены.";if(old>0&&old!=r.Uid)MessageBox.Show($"Сервер вернул другой UID ({r.Uid}). Старый UID ({old}) не используется.","Проверка UID",MessageBoxButtons.OK,MessageBoxIcon.Warning);}catch(Exception e){status.Text=register?"Регистрация не выполнена.":"Вход не выполнен.";if(show)MessageBox.Show(e.Message,register?"Регистрация не выполнена":"Вход не выполнен",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 void SetServer(){try{hosts.SetServer(ip.Text);Save();status.Text="Режим: мой сервер ("+ip.Text.Trim()+")";}catch(Exception e){MessageBox.Show(e.Message,"Не удалось переключить hosts",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 void SetOfficial(){try{hosts.SetOfficial();Save();status.Text="Режим: официальная игра (удалены только записи лаунчера)";}catch(Exception e){MessageBox.Show(e.Message,"Не удалось вернуть официальный режим",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 void Browse(){using var d=new OpenFileDialog{Filter="RF4 executable (rf4_x64.exe)|rf4_x64.exe|Executable (*.exe)|*.exe",Title="Выбери rf4_x64.exe",CheckFileExists=true};if(d.ShowDialog(this)==DialogResult.OK){game.Text=d.FileName;Save();}}
 void Launch(){try{var p=game.Text.Trim().Trim('"');if(!File.Exists(p)||!string.Equals(Path.GetFileName(p),"rf4_x64.exe",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Выбери существующий файл rf4_x64.exe.");var r=string.IsNullOrWhiteSpace(region.Text)?"CN":region.Text.Trim();if(!Regex.IsMatch(r,"^[A-Za-z0-9_-]+$"))throw new InvalidOperationException("Регион может содержать только латинские буквы, цифры, _ и -.");Save();Process.Start(new ProcessStartInfo{FileName=p,WorkingDirectory=Path.GetDirectoryName(p)!,UseShellExecute=true,Arguments="-region "+r});status.Text="Игра запущена. Используется выбранный выше режим подключения.";}catch(Exception e){MessageBox.Show(e.Message,"Не удалось запустить игру",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
}
